package main

import (
	"context"
	"errors"
	"fmt"
	"log"
	"os"
	"time"

	"github.com/elyonar/einvoice-go"
)

func main() {
	ctx := context.Background()

	yona, err := einvoice.New(os.Getenv("YONA_API_KEY"),
		einvoice.WithTimeout(30*time.Second),
		einvoice.WithRetry(einvoice.RetryConfig{MaxRetries: einvoice.Ptr(3), BaseDelay: 500 * time.Millisecond, MaxRetryAfter: 30 * time.Second}),
	)
	if err != nil {
		log.Fatal(err)
	}

_, err = yona.Invoices.Create(ctx, &einvoice.CreateInvoiceBody{InvoiceKind: "B2B", InvoiceDate: "2026-10-05", Currency: "NGN", LineItems: []einvoice.InvoiceLineItemDto{}})
var validation *einvoice.ValidationError
if !errors.As(err, &validation) {
	log.Fatal("expected a validation error, got ", err)
}
fmt.Println(validation.Status, validation.ErrorCode, validation.RequestID)
for _, e := range validation.Errors {
	fmt.Printf("  %s: %s\n", e.Field, e.Message)
}

idempotencyKey := "order-" + einvoice.GenerateIdempotencyKey()
params := &einvoice.CreateInvoiceBody{
	InvoiceKind: "B2C",
	InvoiceDate: time.Now().Format("2006-01-02"),
	Currency:    "NGN",
	LineItems: []einvoice.InvoiceLineItemDto{{
		ItemName:        einvoice.Ptr("Consulting hour"),
		Description:     einvoice.Ptr("Consulting hour"),
		UnitCode:        einvoice.Ptr("EA"),
		Quantity:        einvoice.AmountNumber(1),
		UnitPrice:       einvoice.Ptr(einvoice.AmountString("25000.00")),
		TaxCategory:     einvoice.Ptr("STANDARD_VAT"),
		ISICCode:        einvoice.Ptr("6201"),
		ServiceCategory: einvoice.Ptr("Professional services"),
	}},
}
first, err := yona.Invoices.Create(ctx, params, einvoice.WithIdempotencyKey(idempotencyKey))
if err != nil {
	log.Fatal(err)
}
again, err := yona.Invoices.Create(ctx, params, einvoice.WithIdempotencyKey(idempotencyKey))
if err != nil {
	log.Fatal(err)
}
fmt.Println("same invoice on retry:", first.ID == again.ID)
if first.ID != again.ID {
	log.Fatal("an idempotent retry created a second invoice")
}

withRetry := func(call func() (*einvoice.Page[einvoice.ListInvoicesItem], error), attempts int) (*einvoice.Page[einvoice.ListInvoicesItem], error) {
	for attempt := 1; ; attempt++ {
		page, err := call()
		var rateLimited *einvoice.RateLimitError
		var server *einvoice.ServerError
		var timeout *einvoice.TimeoutError
		var connection *einvoice.ConnectionError
		transient := errors.As(err, &rateLimited) || errors.As(err, &server) || errors.As(err, &timeout) || errors.As(err, &connection)
		if err == nil || !transient || attempt >= attempts {
			return page, err
		}
		seconds := 1 << attempt
		var refusal *einvoice.APIError
		if errors.As(err, &refusal) && refusal.RetryAfter > 0 {
			seconds = refusal.RetryAfter
		}
		time.Sleep(time.Duration(seconds) * time.Second)
	}
}
page, err := withRetry(func() (*einvoice.Page[einvoice.ListInvoicesItem], error) {
	return yona.Invoices.List(ctx, &einvoice.ListInvoicesQuery{Limit: einvoice.Ptr(5.0)})
}, 3)
if err != nil {
	log.Fatal(err)
}
fmt.Println("invoices", page.Pagination.Total, "request", page.RequestID)

	if _, err := yona.Invoices.Delete(ctx, first.ID); err != nil {
		log.Fatal(err)
	}
}

readiness, err := yona.Organization.GetReadiness(ctx)
if err != nil {
	log.Fatal(err)
}
out, _ := json.MarshalIndent(readiness, "", "  ")
fmt.Println(string(out))

other := einvoice.ModeLive
if yona.Mode() == einvoice.ModeLive {
	other = einvoice.ModeSandbox
}
_, err = einvoice.New(os.Getenv("YONA_API_KEY"), einvoice.WithAssertMode(other))
var refused *einvoice.ConfigError
if !errors.As(err, &refused) {
	log.Fatal("WithAssertMode did not refuse a key of the other mode")
}
fmt.Println("refused:", refused.Message)

if yona.Mode() == einvoice.ModeSandbox {
	usage, err := yona.Billing.Sandbox.GetUsage(ctx)
	if err != nil {
		log.Fatal(err)
	}
	fmt.Println("sandbox credits", usage.CreditsUsed, "used of", usage.CreditsLimit, "until", usage.PeriodEnd)
}

connection, err := yona.TaxConnection.Get(ctx)
if err != nil {
	log.Fatal(err)
}
fmt.Println("tax connection", connection.Mode, connection.Kind, connection.State)

	client, err := einvoice.New(os.Getenv("YONA_API_KEY"))
	if err != nil {
		log.Fatal(err)
	}
	if client.Mode() == einvoice.ModeLive {
		fmt.Println("live: submissions are reported to the tax authority")
	} else {
		fmt.Println("sandbox: deploy an sk_live_ key to go live")
	}
}

package main

import (
	"context"
	"encoding/json"
	"fmt"
	"log"
	"os"

	"github.com/elyonar/einvoice-go"
)

// text prints an optional string field: its value, or "-" when the API sent null.
func text(p *string) string {
	if p == nil {
		return "-"
	}
	return *p
}

func main() {
	ctx := context.Background()

	yona, err := einvoice.New(os.Getenv("YONA_API_KEY"))
	if err != nil {
		log.Fatal(err)
	}

connection, err := yona.TaxConnection.Get(ctx)
if err != nil {
	log.Fatal(err)
}
fmt.Println("tax connection", connection.Mode, connection.Kind, connection.State)

first, err := yona.InboundInvoices.List(ctx, &einvoice.ListInboundInvoicesQuery{Limit: einvoice.Ptr(20.0)})
if err != nil {
	log.Fatal(err)
}
total := int64(len(first.Data.Items))
if first.Pagination != nil {
	total = first.Pagination.Total
}
fmt.Println("received", total, "syncing", first.Data.Sync.Syncing)
for _, inv := range first.Data.Items {
	supplier := inv.SupplierName
	if supplier == nil {
		supplier = inv.SupplierTIN
	}
	payable := 0.0
	if inv.PayableAmountMinor != nil {
		payable = *inv.PayableAmountMinor
	}
	fmt.Println(inv.Irn, text(supplier), payable, text(inv.Currency), inv.PaymentStatus)
}

unpaid, err := yona.InboundInvoices.List(ctx, &einvoice.ListInboundInvoicesQuery{
	PaymentStatus: einvoice.Ptr(einvoice.ListInboundInvoicesQueryPaymentStatusUnpaid),
	Sort:          einvoice.Ptr(einvoice.ListInboundInvoicesQuerySortDescIssueDate),
	Limit:         einvoice.Ptr(20.0),
})
if err != nil {
	log.Fatal(err)
}
fmt.Println("unpaid on this page", len(unpaid.Data.Items))

count := 0
query := &einvoice.ListInboundInvoicesQuery{Limit: einvoice.Ptr(50.0)}
err = einvoice.Paginate(ctx, func(ctx context.Context, page int64) (*einvoice.Page[einvoice.InboundInvoiceViewDto], error) {
	query.Page = einvoice.Ptr(float64(page))
	res, err := yona.InboundInvoices.List(ctx, query)
	if err != nil {
		return nil, err
	}
	out := &einvoice.Page[einvoice.InboundInvoiceViewDto]{Data: res.Data.Items, RequestID: res.RequestID}
	if res.Pagination != nil {
		out.Pagination = *res.Pagination
	}
	return out, nil
}, func(inv einvoice.InboundInvoiceViewDto) error {
	count++
	if count <= 3 {
		fmt.Println(inv.Irn)
	}
	return nil
})
if err != nil {
	log.Fatal(err)
}
fmt.Println("walked", count, "received invoices")

if len(first.Data.Items) > 0 {
	one, err := yona.InboundInvoices.Get(ctx, first.Data.Items[0].ID)
	if err != nil {
		log.Fatal(err)
	}
	detail, _ := json.MarshalIndent(one, "", "  ")
	fmt.Println(string(detail))
}

analytics, err := yona.InboundInvoices.GetAnalytics(ctx, nil)
if err != nil {
	log.Fatal(err)
}
summary, _ := json.MarshalIndent(analytics, "", "  ")
fmt.Println(string(summary))

	buyersQuery := &einvoice.ListBuyersQuery{Limit: einvoice.Ptr(100.0)}
